/* Phase 4: independently authored A1.1 audio-first learning prompts. Device-generated German speech; no publisher or human recordings. */
(()=>{
'use strict';
const data={"a11-greetings":{"chapter":1,"title":"Greet a classmate and a teacher","questions":[{"audio":"Guten Tag. Ich heiße Eva. Wie heißen Sie?","prompt":"Is the speaker addressing someone politely?","options":["Yes, formally","No, informally","She is asking the time"],"correct":0,"explanation":"The phrase Wie heißen Sie? uses the formal address."},{"audio":"Hallo, ich bin Tim. Wie heißt du?","prompt":"How does the speaker ask for a name?","options":["With a formal Sie question","With an informal du question","By asking a price"],"correct":1,"explanation":"Wie heißt du? uses the informal form."}],"phrase":"Guten Tag! Ich heiße Emma. Wie heißen Sie?","checklist":["I use a suitable greeting.","I use Sie for a polite question.","I say heißen clearly."]},"a11-origin-spelling":{"chapter":1,"title":"Understand origins, residence and spelling","questions":[{"audio":"Ich komme aus Nepal, aber ich wohne in München.","prompt":"Where does the person live?","options":["In Nepal","In München","In Hamburg"],"correct":1,"explanation":"Wohne in München tells us where the person lives, not where they come from."},{"audio":"Ich spreche Deutsch und Englisch. Mein Name ist Lea.","prompt":"Which languages does the person speak?","options":["German and English","Only English","French and German"],"correct":0,"explanation":"Deutsch und Englisch names the two languages."}],"phrase":"Ich komme aus Indien. Ich wohne in Berlin.","checklist":["I distinguish komme aus and wohne in.","I say the country and city clearly.","I pause between sentences."]},"a11-hobbies":{"chapter":2,"title":"Listen for hobbies and plans","questions":[{"audio":"Ich spiele gern Fußball, aber heute muss ich lernen.","prompt":"What does the speaker like doing?","options":["Reading","Playing football","Cycling"],"correct":1,"explanation":"Spiele gern Fußball expresses enjoyment of playing football."},{"audio":"Am Freitag habe ich keine Zeit. Am Samstag gehe ich ins Kino.","prompt":"When is the cinema plan?","options":["On Thursday","On Friday","On Saturday"],"correct":2,"explanation":"Am Samstag is when the speaker goes to the cinema."}],"phrase":"Hast du am Samstag Zeit? Wir können ins Kino gehen.","checklist":["I ask about a day using am.","I put the question verb first.","I pronounce Samstag clearly."]},"a11-jobs-seasons":{"chapter":2,"title":"Recognise jobs, hours and seasons","questions":[{"audio":"Meine Schwester ist Ärztin. Sie arbeitet im Krankenhaus.","prompt":"Where does the sister work?","options":["At a school","At a hospital","At a restaurant"],"correct":1,"explanation":"Im Krankenhaus identifies the workplace."},{"audio":"Im Winter arbeite ich von neun bis fünfzehn Uhr.","prompt":"When does the workday end?","options":["At nine","At twelve","At fifteen o'clock"],"correct":2,"explanation":"Von neun bis fünfzehn Uhr means from 9 until 15:00."}],"phrase":"Ich bin Koch. Ich arbeite von zehn bis achtzehn Uhr.","checklist":["I say the occupation without an extra article.","I use von … bis for hours.","I speak the numbers distinctly."]},"a11-city-places":{"chapter":3,"title":"Listen for city places and negation","questions":[{"audio":"Hier gibt es ein Museum und eine Bank.","prompt":"Which two places are mentioned?","options":["A museum and a bank","A station and a bank","A museum and a station"],"correct":0,"explanation":"Ein Museum und eine Bank names both places."},{"audio":"In dieser Straße gibt es keinen Bahnhof.","prompt":"What is missing in the street?","options":["A bank","A train station","A café"],"correct":1,"explanation":"Keinen Bahnhof says that there is no station."}],"phrase":"Hier gibt es einen Bahnhof und ein Museum.","checklist":["I use einen with Bahnhof after es gibt.","I pronounce the place names clearly.","I separate the two destinations."]},"a11-city-directions":{"chapter":3,"title":"Follow simple instructions","questions":[{"audio":"Entschuldigung! Gehen Sie geradeaus und dann nach links.","prompt":"What happens after going straight?","options":["Turn right","Turn left","Take a bus"],"correct":1,"explanation":"Nach links means turn left."},{"audio":"Fahren Sie mit dem Bus zum Museum. Die Haltestelle ist dort.","prompt":"How should the visitor travel?","options":["By train","On foot","By bus"],"correct":2,"explanation":"Mit dem Bus indicates bus travel."}],"phrase":"Gehen Sie geradeaus und dann nach rechts.","checklist":["I say the polite command Gehen Sie.","I distinguish rechts from links.","I speak each step in order."]},"a11-food-shops":{"chapter":4,"title":"Recognise food and shopping needs","questions":[{"audio":"Zum Mittagessen brauchen wir Brot, Käse und Tomaten.","prompt":"Which food is not mentioned?","options":["Bread","Tomatoes","Rice"],"correct":2,"explanation":"The list includes Brot, Käse and Tomaten but no Reis."},{"audio":"Ich kaufe zwei Brötchen in der Bäckerei.","prompt":"Where is the shopping happening?","options":["At a bakery","At a pharmacy","At a museum"],"correct":0,"explanation":"In der Bäckerei names the bakery."}],"phrase":"Wir brauchen Brot, Käse und zwei Tomaten.","checklist":["I say each food clearly.","I keep the noun articles in mind.","I pronounce zwei Tomaten as a quantity."]},"a11-accusative-restaurant":{"chapter":4,"title":"Listen for polite purchases","questions":[{"audio":"Ich möchte einen Tee und ein Brötchen, bitte.","prompt":"What drink does the customer order?","options":["Coffee","Tea","Water"],"correct":1,"explanation":"Einen Tee refers to tea."},{"audio":"Was kostet ein Kilo Äpfel? Drei Euro, bitte.","prompt":"How much is one kilogram of apples?","options":["Two euros","Four euros","Three euros"],"correct":2,"explanation":"Drei Euro is the stated price."}],"phrase":"Ich möchte einen Apfel und einen Tee, bitte.","checklist":["I use the accusative einen.","I say bitte politely.","I pronounce both items distinctly."]},"a11-daily-time":{"chapter":5,"title":"Hear clock times and daily routines","questions":[{"audio":"Es ist halb acht. Ich muss jetzt zur Arbeit.","prompt":"What time is it?","options":["07:30","08:30","07:45"],"correct":0,"explanation":"Halb acht is 07:30, halfway to eight."},{"audio":"Um acht Uhr fahre ich zur Arbeit. Um sechs Uhr bin ich wieder zu Hause.","prompt":"When does the person leave for work?","options":["At six","At eight","At nine"],"correct":1,"explanation":"Um acht Uhr is the departure time."}],"phrase":"Um halb acht frühstücke ich. Dann fahre ich zur Arbeit.","checklist":["I understand halb acht means 07:30.","I keep the verb after an opening time phrase.","I speak the routine naturally."]},"a11-family-appointments":{"chapter":5,"title":"Listen for family and appointments","questions":[{"audio":"Meine Schwester heißt Lara. Sie wohnt in Köln.","prompt":"Who lives in Cologne?","options":["The speaker's brother","The speaker's sister","The speaker's teacher"],"correct":1,"explanation":"Meine Schwester refers to the sister."},{"audio":"Am Mittwoch habe ich keine Zeit. Können wir uns am Donnerstag treffen?","prompt":"Which day is suggested instead?","options":["Tuesday","Wednesday","Thursday"],"correct":2,"explanation":"Am Donnerstag is the proposed alternative day."}],"phrase":"Hast du am Donnerstag um fünfzehn Uhr Zeit?","checklist":["I use am for the day.","I use um for the clock time.","I ask clearly whether the person is available."]},"a11-birthdays-invitations":{"chapter":6,"title":"Listen for dates and invitations","questions":[{"audio":"Meine Geburtstagsparty ist am zwölften Mai um achtzehn Uhr.","prompt":"When does the party start?","options":["At 18:00","At 12:00","At 20:00"],"correct":0,"explanation":"Um achtzehn Uhr is 6 p.m."},{"audio":"Kommst du am Samstag? Leider kann ich nicht. Ich komme am Sonntag.","prompt":"When can the second speaker come?","options":["Saturday","Sunday","Friday"],"correct":1,"explanation":"Ich komme am Sonntag gives the alternative day."}],"phrase":"Kommst du am Samstag zu meiner Party?","checklist":["I use the verb-first invitation question.","I pronounce Samstag and Party clearly.","I use zu meiner Party correctly."]},"a11-restaurant-past":{"chapter":6,"title":"Understand a meal and the past","questions":[{"audio":"Die Rechnung, bitte. Wir möchten jetzt zahlen.","prompt":"What does the guest want?","options":["The menu","The bill","A map"],"correct":1,"explanation":"Die Rechnung and zahlen indicate payment."},{"audio":"Gestern war ich im Restaurant. Ich hatte eine Suppe.","prompt":"What did the speaker have yesterday?","options":["A soup","A salad","A tea"],"correct":0,"explanation":"Ich hatte eine Suppe reports the past meal."}],"phrase":"Gestern war ich im Restaurant. Das Essen war gut.","checklist":["I use war for the past.","I pronounce gestern distinctly.","I keep the two sentences fluent."]}};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function stats(id,byLesson){const d=data[id],p=byLesson?.[id]||{},answers=p.answers||{};return {total:d?.questions.length||0,answered:d?.questions.filter((q,i)=>!!answers[i]).length||0,correct:d?.questions.filter((q,i)=>answers[i]?.correct).length||0,reflected:!!p.reflected};}
function render(id,byLesson,choices,rate,voiceURI,voices,recording,recordedURL){
 const d=data[id];if(!d)return '';
 const p=byLesson?.[id]||{},answers=p.answers||{},score=stats(id,byLesson);
 const speed=rate==='slow'?'slow':'normal';
 const germanVoices=Array.isArray(voices)?voices.filter(v=>/^de(-|$)/i.test(v.lang||'')):[];
 const voiceOptions=germanVoices.map(v=>'<option value="'+esc(v.voiceURI||v.name)+'" '+((v.voiceURI||v.name)===voiceURI?'selected':'')+'>'+esc(v.name)+' ('+esc(v.lang)+')</option>').join('');
 return '<section class="p4-lab" aria-label="German listening and speaking practice"><header class="p4-header"><span class="eyebrow">Original A1.1 listening and speaking · Chapter '+d.chapter+'</span><h2>Hear it. Say it. Make it yours.</h2><p>'+esc(d.title)+'. Complete two short listening tasks and practise one spoken response. This is not an official pronunciation score.</p></header>'+
 '<section class="p4-control"><div><strong>German playback</strong><span>Listen at a comfortable pace. Playback uses a German speech voice installed in your browser or device.</span></div><div class="p4-speeds" role="group" aria-label="Playback speed"><button type="button" data-p4-speed="slow" aria-pressed="'+(speed==='slow')+'" class="'+(speed==='slow'?'selected':'')+'">Slow · 0.7×</button><button type="button" data-p4-speed="normal" aria-pressed="'+(speed==='normal')+'" class="'+(speed==='normal'?'selected':'')+'">Normal · 0.95×</button></div>'+
 (germanVoices.length?'<label class="p4-voice">German voice<select data-p4-voice><option value="">Device default</option>'+voiceOptions+'</select></label>':'<p class="p4-voice-note">A German voice might not be installed. If playback fails, check your device speech-language settings.</p>')+'</section>'+
 '<section class="p4-listen"><div class="p4-section-title"><div><span class="eyebrow">01 · Listen and understand</span><h3>What did you hear?</h3></div><span>'+score.correct+'/'+score.total+' correct</span></div>'+
 d.questions.map((q,i)=>{const a=answers[i],selected=choices?.[id+':'+i];return '<article class="p4-question"><div class="p4-qhead"><b>Listening '+(i+1)+'</b><span>'+(a?(a.correct?'✓ Correct':'Review and retry'):'Audio first')+'</span></div><div class="p4-play"><button type="button" class="btn btn-primary btn-small" data-p4-play="'+id+'|'+i+'">♫ Play phrase</button><button type="button" class="btn btn-outline btn-small" data-p4-play-slow="'+id+'|'+i+'">♫ Play slowly</button><small>Listen before reading. The transcript appears after you check.</small></div><h4>'+esc(q.prompt)+'</h4><div class="p4-options" role="group" aria-label="'+esc(q.prompt)+'">'+q.options.map((o,j)=>'<button type="button" data-p4-choice="'+id+'|'+i+'|'+j+'" class="p4-option '+(selected===j?'selected ':'')+(a&&j===q.correct?'correct ':'')+(a&&a.chosen===j&&!a.correct?'incorrect':'')+'" aria-pressed="'+(selected===j)+'" '+(a?'disabled':'')+'>'+esc(o)+'</button>').join('')+'</div>'+
 (a?'<div class="p4-feedback '+(a.correct?'':'needs-review')+'" role="status"><b>'+(a.correct?'Correct.':'Not quite.')+'</b> '+esc(q.explanation)+'<p><b>Transcript:</b> <span lang="de">'+esc(q.audio)+'</span></p><button type="button" class="view-link" data-p4-retry="'+id+'|'+i+'">Retry this question</button></div>':'<button type="button" class="btn btn-primary btn-small" data-p4-check="'+id+'|'+i+'" '+(selected===undefined?'disabled':'')+'>Check answer</button>')+'</article>';}).join('')+'</section>'+
 '<section class="p4-speaking"><span class="eyebrow">02 · Practise speaking</span><h3>Repeat, record, and reflect</h3><p>Listen to the model phrase. Say it slowly, then at normal speed. Optionally record yourself and replay it for comparison.</p><div class="p4-speaking-model"><div><span>Model sentence</span><strong lang="de">'+esc(d.phrase)+'</strong></div><div><button type="button" class="btn btn-outline btn-small" data-p4-model="'+id+'">♫ Listen</button><button type="button" class="btn btn-outline btn-small" data-p4-model-slow="'+id+'">♫ Slow replay</button></div></div>'+
 '<div class="p4-record-row"><button type="button" class="btn btn-outline btn-small" data-p4-record="'+id+'">'+(recording?'■ Stop recording':'● Record my voice')+'</button>'+(recordedURL?'<audio controls preload="none" src="'+esc(recordedURL)+'" aria-label="Play your local speaking recording"></audio>':'<span>Optional. Your recording is kept only in memory on this device, not uploaded or saved in the browser database.</span>')+'</div>'+
 '<fieldset class="p4-checklist"><legend>My self-review · select what you practised</legend>'+d.checklist.map((c,i)=>'<label><input type="checkbox" data-p4-reflect="'+id+'|'+i+'" '+(p.reflection?.[i]?'checked':'')+' /> <span>'+esc(c)+'</span></label>').join('')+'</fieldset><p class="p4-note">These checkmarks are self-reported rehearsal steps, not automatic pronunciation accuracy or certification results. Your teacher can see the checklist completion in this same-browser demo.</p></section></section>';
}
window.GERMAN_AUDIO_LABS={data,render,stats};
})();